const CO='<i class="co tl"></i><i class="co tr"></i><i class="co br"></i><i class="co bl"></i>';
const hl=(code,lang)=>{const L=esc(code).split('\n'),more=L.length>4;return L.slice(0,4).map((l,i)=>{
  let x=l.replace(/(\/\/.*$|\/\*.*?\*\/)/,'<span class="cc">$1</span>');
  x=x.replace(/\b(export|function|const|let|return|pub|struct|use|fn|import|from|Option|default)\b/g,'<span class="ck">$1</span>');
  return `<span class="ln${i===3&&more?' more':''}">${x||' '}</span>`}).join('')};
const pmSvg=(it,n)=>{const d=new Date(it.at);const id='clPm'+(++st.seq);
  return `<svg class="pm" viewBox="0 0 78 62" aria-hidden="true"><path id="${id}" d="M30 31 m-17 0 a17 17 0 1 1 34 0 a17 17 0 1 1 -34 0" fill="none" stroke="none"/>
  <circle cx="30" cy="31" r="22"/><circle cx="30" cy="31" r="12.5"/><text><textPath href="#${id}" startOffset="1">KIMI CODE ✦ ${esc(M[d.getMonth()]||'').toUpperCase()} ✦</textPath></text>
  <text class="pd" x="30" y="34" text-anchor="middle">${isNaN(d)?'':d.getDate()}</text>
  <path class="w" d="M50 22 q5 -3 10 0 t10 0 t10 0"/><path class="w" d="M52 31 q5 -3 10 0 t10 0 t10 0"/><path class="w" d="M50 40 q5 -3 10 0 t10 0 t10 0"/></svg>`};
const piece=(it,n)=>{const no=pad(n);
  if(it.kind==='chat')return `<div class="pc stp" data-k="chat"><i class="sperf"></i><div class="fr"><img class="sart" src="${IMG[it.art]||IMG.catalog}" alt="" draggable="false"></div>
    <span class="dn"><small>N°</small>${no}</span><b class="nm">${esc(it.title)}</b>${pmSvg(it,n)}${CO}</div>`;
  if(it.kind==='code')return `<div class="pc ic" data-k="code"><img class="clip" src="${IMG.clip}" alt="" draggable="false"><div class="hd"><b>${esc(it.title)}</b><i>${esc(it.lang||'TXT')}</i></div>
    <div class="cd">${hl(it.code||'',it.lang)}</div><div class="ft"><span>FICHE N° ${no}</span><span>${esc(fdate(it.at))}</span></div>${CO}</div>`;
  if(it.kind==='file')return `<div class="pc tg" data-k="file"><svg class="sh" viewBox="0 0 122 170" aria-hidden="true">
    <path class="str" d="M61 20 C 64 6, 80 -8, 96 -18"/>
    <path class="o" d="M24 2 H98 L120 24 V166 Q120 169 117 169 H5 Q2 169 2 166 V24 Z"/><path class="i" d="M26 7 H96 L115 26 V164 H7 V26 Z"/>
    <circle class="ey" cx="61" cy="20" r="9"/><circle class="ey2" cx="61" cy="20" r="4.2"/></svg>
    <div class="lb"><small>BAGAGE · FICHIER</small><em>Étiquette</em><b>${esc(it.title)}</b><span>${esc(it.ext||'')} · ${esc(it.size||'')}<br>N° ${no} · ${esc(fdate(it.at))}</span></div><i class="co br"></i><i class="co bl"></i></div>`;
  const host=(()=>{try{return new URL(it.url).host}catch(e){return it.url||''}})();
  return `<div class="pc ps" data-k="web"><div class="pvw"><img src="${IMG[it.art]||IMG.observatory}" alt="" draggable="false"><small>Souvenir</small></div><i class="dv"></i><i class="sb"></i>
    <div class="ad"><b>${esc(it.title)}</b><span>${esc(host)}</span><i>N° ${no}</i></div>${CO}</div>`};

